-- Individually selected counterarguments and point-specific sources.
update dk_safety.points set counterpoint='Protect household bills. Residents need to know who would cover grid costs if the operator uses less power than it promised.' where slug='ai-data-centers' and id='75285951-7ad5-5fec-b901-d24bca832d2c';
update dk_safety.points set counterpoint='Charge for power upgrades. An agreement can require the operator to pay for new substations and power lines needed by the project.' where slug='ai-data-centers' and id='175d2743-9744-513f-98f8-b99201133808';
update dk_safety.points set counterpoint='Read the tax breaks. A headline investment figure tells residents little about how much revenue their community will keep.' where slug='ai-data-centers' and id='67b9ec5b-4113-5596-9bc9-0f5c06e99bf1';
update dk_safety.points set counterpoint='Add local tax revenue. Property tax receipts could support local services if tax breaks leave a meaningful share for the town.' where slug='ai-data-centers' and id='e992706e-01fe-5c8d-9e8c-5b8c921ae091';
update dk_safety.points set counterpoint='Count lasting jobs. Ask how many jobs will remain after construction and compare that number with the public investment.' where slug='ai-data-centers' and id='c841c516-7080-5c01-a5ec-30e524be0f42';
update dk_safety.points set counterpoint='Create construction jobs. A large project can bring work for electricians, builders, and other trades during construction.' where slug='ai-data-centers' and id='847e3209-3f84-5522-a25c-d29d378656d3';
update dk_safety.points set counterpoint='Compare other land uses. The same site might support another project with more permanent jobs or different infrastructure needs.' where slug='ai-data-centers' and id='d154780a-8ccc-5a5d-91d2-9d65d5166829';
update dk_safety.points set counterpoint='Reuse an industrial site. A site already set aside for industry may be suitable if power and water are available there.' where slug='ai-data-centers' and id='620d1a89-7c79-5822-9de4-a5ecd5bd04e5';
update dk_safety.points set counterpoint='Check drought demand. Even a project that fits normal water supplies may cause problems in a dry year.' where slug='ai-data-centers' and id='1ff81dff-eadf-5b79-9349-5e454bef6224';
update dk_safety.points set counterpoint='Set a water limit. A permit can cap water use and require the operator to change how it cools equipment during shortages.' where slug='ai-data-centers' and id='3b64b4ef-9bbc-59df-8ef3-9d113ed5e0a5';
update dk_safety.points set counterpoint='Test overnight noise. Fans and backup equipment may be more noticeable at night, so residents need a study based on local conditions.' where slug='ai-data-centers' and id='61cd6605-fdb7-5a14-a843-9e2756409e53';
update dk_safety.points set counterpoint='Control noise by permit. Setbacks and limits on overnight noise can help protect nearby homes.' where slug='ai-data-centers' and id='55c1bb96-8222-51bf-995b-6fcd88b0d8bc';
update dk_safety.points set counterpoint='Check enforcement powers. Any promised limits need clear penalties and someone responsible for enforcing them.' where slug='ai-data-centers' and id='1ac54127-436a-5342-97cf-a9547dc53796';
update dk_safety.points set counterpoint='Require public reporting. Publishing energy use, water use, and complaints would let residents see whether the operator meets its promises.' where slug='ai-data-centers' and id='afdb6c6a-6d31-596f-b1c6-82afdba2c54d';
update dk_safety.points set sources=jsonb_build_array('https://puco.ohio.gov/utilities/electricity/resources/data-centers') where slug='ai-data-centers' and id='75285951-7ad5-5fec-b901-d24bca832d2c';
update dk_safety.points set sources=jsonb_build_array('https://puco.ohio.gov/news/process-protects-aep-customers-from-potential-data-center-costs') where slug='ai-data-centers' and id='175d2743-9744-513f-98f8-b99201133808';
update dk_safety.points set sources=jsonb_build_array('https://seta.lbl.gov/publications/2024-lbnl-data-center-energy-usage-report') where slug='ai-data-centers' and id='3b64b4ef-9bbc-59df-8ef3-9d113ed5e0a5';
update dk_safety.points set counterpoint='Check retail savings. Some stores or distributors may keep part of the savings, so a tariff cut may deliver less relief than expected.' where slug='grocery-tariffs' and id='502ca531-c9d6-5be8-b950-83c68ea6931e';
update dk_safety.points set counterpoint='Ease checkout costs. Lower import costs can help shoppers if wholesalers and grocery stores pass the savings along.' where slug='grocery-tariffs' and id='241cd8c2-fbc0-529b-8ba2-f957fe3d8521';
update dk_safety.points set counterpoint='Keep negotiating leverage. Tariffs can give negotiators something to remove in exchange for lower trade barriers on U.S. exports.' where slug='grocery-tariffs' and id='33ab37c3-3cd8-5ad7-9649-3e1fe0953b5f';
update dk_safety.points set counterpoint='Reduce trade friction. A rollback can give trading partners an opening to remove duties on some U.S. farm exports.' where slug='grocery-tariffs' and id='752225d4-4700-58c1-af5e-9dcaf51cab3f';
update dk_safety.points set counterpoint='Review foods individually. A food with a strong domestic industry presents a different tradeoff from one the country mostly imports.' where slug='grocery-tariffs' and id='61f524a4-6b64-5dbf-aa9d-052b4150f0a7';
update dk_safety.points set counterpoint='Match sudden shortages. Open access to foreign supply can help stores restock after weather damages a domestic harvest.' where slug='grocery-tariffs' and id='5fd33304-d577-5a0d-b72c-286ae6c551b2';
update dk_safety.points set counterpoint='Lower costs at visits. A lower premium helps with the monthly bill, while a smaller deductible could make medical visits easier to afford.' where slug='health-insurance' and id='f7a71797-a47c-52b9-afb5-48ceb0c3cc3a';
update dk_safety.points set counterpoint='Lower monthly premiums. Larger tax credits can reduce what eligible households pay each month for plans they buy through the marketplace.' where slug='health-insurance' and id='8c8f2652-faa3-5b78-b7c5-544fef9c6d49';
update dk_safety.points set counterpoint='Target limited aid. Congress could concentrate extra assistance on families with the least income or the highest share of income spent on premiums.' where slug='health-insurance' and id='80d3f281-d64d-50f0-8d3e-52d9ad1910d7';
update dk_safety.points set counterpoint='Ease income cutoffs. A gradual phaseout can keep a modest raise from causing a sudden jump in what someone pays for coverage.' where slug='health-insurance' and id='efe90371-07f4-5845-a395-1053cd755b99';
update dk_safety.points set counterpoint='Help outside the marketplace. Lower underlying prices could also help workers with employer plans and people who pay cash for care.' where slug='health-insurance' and id='97a6d3e9-e5c3-5482-a99e-ad801f71ff9f';
update dk_safety.points set counterpoint='Use existing marketplaces. An updated credit can use the same enrollment process people already use to apply for financial help.' where slug='health-insurance' and id='37b63d09-12d6-5721-8a95-0e4bcef1c198';
update dk_safety.points set counterpoint='Continuous learning. Autoplay can help students follow a lecture series or tutorial playlist in order.' where slug='teen-autoplay' and id='5156b51c-4417-581e-9739-afe192ff1698';
update dk_safety.points set counterpoint='A natural stopping point. Ending each video gives teens a moment to decide if they want to watch another.' where slug='teen-autoplay' and id='15b54321-9cff-5ea2-a4e2-a777c67bf371';
update dk_safety.points set counterpoint='Family judgment. Caregivers can choose settings that fit how and when a teen uses an app.' where slug='teen-autoplay' and id='eb339ae0-2e83-54c9-bddf-445b4a417da8';
update dk_safety.points set counterpoint='Easier family rules. A common setting makes expectations easier to explain across apps.' where slug='teen-autoplay' and id='950d2bd0-e528-505b-b4ad-e12d73f7193f';
update dk_safety.points set counterpoint='Age checks cost privacy. Some approaches to enforcing an age rule could ask for extra personal information.' where slug='teen-autoplay' and id='8621698d-8877-5243-b682-ad1370592755';
update dk_safety.points set counterpoint='Less checking for parents. A default lets parents spend less time finding settings on each service.' where slug='teen-autoplay' and id='8feb403e-1c27-521d-88ad-01e23ca50129';
update dk_safety.points set counterpoint='Confidential information. Private briefings can let lawmakers ask questions about sensitive information.' where slug='iran-war-powers' and id='a35a2181-e74e-5d27-8e26-d69bc9d18fac';
update dk_safety.points set counterpoint='Public accountability. A recorded vote makes it clear where each elected lawmaker stands.' where slug='iran-war-powers' and id='f682d3ba-c0ad-5fe0-8f2f-7d74c4ffa2cd';
update dk_safety.points set counterpoint='Flexible timing. A review tied to meaningful changes may reveal more than a vote on a fixed date.' where slug='iran-war-powers' and id='88012770-2e7a-51da-b14b-368f6fd26eb7';
update dk_safety.points set counterpoint='A deadline to review. Congress could require renewed approval after a set period.' where slug='iran-war-powers' and id='4b63aeb4-4ab4-5052-8945-464187af5a77';
update dk_safety.points set counterpoint='Funding reviews. Congress can use funding debates to challenge spending and set conditions.' where slug='iran-war-powers' and id='47edf1e2-2de1-57f1-b41e-e243d9a631d1';
update dk_safety.points set counterpoint='Visible costs. Debate gives the public a place to ask how continuing the conflict affects spending and other priorities.' where slug='iran-war-powers' and id='d811d91c-0ed6-514d-8d27-376854ed4b9c';
update dk_safety.points set counterpoint='Savings may not pass through. Retail prices may fall by less than the amount of the suspended tax.' where slug='federal-gas-tax' and id='8a2e8688-cce1-5176-b374-f8c45b67da25';
update dk_safety.points set counterpoint='Immediate pump relief. If the tax cut reaches the pump, drivers can benefit when they refill.' where slug='federal-gas-tax' and id='092b7e68-2bb5-57f7-835b-34fd36649e73';
update dk_safety.points set counterpoint='Help follows gallons. People who buy the most fuel could receive more relief regardless of their income.' where slug='federal-gas-tax' and id='7987b071-3865-54bc-8849-966d71570a04';
update dk_safety.points set counterpoint='Help for long commutes. People who have few alternatives to driving could see more relief from a per-gallon cut.' where slug='federal-gas-tax' and id='77ae13a7-b22c-5096-916e-82846b1fd332';
update dk_safety.points set counterpoint='Target the money. Direct support could focus on low-income commuters or people with no practical alternatives.' where slug='federal-gas-tax' and id='7ea601f5-2a48-58ac-a81d-d1432d1a9c5e';
update dk_safety.points set counterpoint='Faster than a rebate. A price change could reach drivers sooner than a new payment system.' where slug='federal-gas-tax' and id='64df1a26-dfeb-5def-a2b1-52a86cbdb7b9';
update dk_safety.points set counterpoint='Protect space for jobs. Keeping some office land available preserves room for employers and future development.' where slug='office-land-housing' and id='d57d79a1-c3a0-5f4e-a4cd-a7e611654af4';
update dk_safety.points set counterpoint='More room for homes. Opening more land gives builders more locations to consider when demand is high.' where slug='office-land-housing' and id='3d5204ab-0141-5804-bb14-4794388382b9';
update dk_safety.points set counterpoint='Safe walking routes. Wide roads and poor sidewalks can make an office district hard to live in.' where slug='office-land-housing' and id='2e21827b-4118-535b-9835-d1afbb6f2b51';
update dk_safety.points set counterpoint='Make use of transit. New homes near an existing station or bus stop can make daily travel easier.' where slug='office-land-housing' and id='216b63eb-b3d9-5230-9784-c004b67886a7';
update dk_safety.points set counterpoint='Hear from neighbors. Site review gives residents a way to flag concrete issues before a project is approved.' where slug='office-land-housing' and id='c27d92a8-7e8d-5935-9442-4cdaf522d76f';
update dk_safety.points set counterpoint='Predictable rules. A clear rule for apartments can make projects easier to plan and review.' where slug='office-land-housing' and id='19bdb646-b1b2-5d9b-ae5b-14bd272ed3f3';
update dk_safety.points set counterpoint='Let each vote stand. Separate votes show where each lawmaker stands on border security and citizenship.' where slug='immigration-bill' and id='876c2685-078e-524a-bad2-e858a98e8f3a';
update dk_safety.points set counterpoint='A deal for both sides. One package gives lawmakers a reason to support changes that they might block if each came up alone.' where slug='immigration-bill' and id='37458446-bc10-5c3c-9684-a7b7f375f4a1';
update dk_safety.points set counterpoint='Clearer budget choices. Separate funding debates can show what each policy costs and what Congress is paying for.' where slug='immigration-bill' and id='83c14fc1-a6b7-5477-97d0-6ce44bc3a5cf';
update dk_safety.points set counterpoint='Budget the whole plan. Lawmakers can see the combined cost of staffing, technology, and processing applications before they vote.' where slug='immigration-bill' and id='176b1e98-07c3-58fe-91a3-ecc731437e0e';
update dk_safety.points set counterpoint='Avoid forced tradeoffs. A lawmaker can support a proposal on its merits without accepting unrelated terms.' where slug='immigration-bill' and id='09a7cf2d-6599-533f-9871-37540be09116';
update dk_safety.points set counterpoint='Room for tradeoffs. Negotiators can trade commitments on funding, eligibility, and timelines to build broader support.' where slug='immigration-bill' and id='98c5b1d8-2c96-5745-af55-5c5b4c3291a8';
update dk_safety.points set counterpoint='Improve plans as costs change. National dates can change when technology, borrowing costs, and energy demand shift.' where slug='fossil-fuel-deadline' and id='37b4a306-fc87-5b9c-b8cc-f2e75839834e';
update dk_safety.points set counterpoint='Investment needs a date. A common deadline can tell utilities and manufacturers when to plan for new equipment and power sources.' where slug='fossil-fuel-deadline' and id='cb8b62df-e1b6-50a1-9c94-4ecf304d99e7';
update dk_safety.points set counterpoint='Protect local jobs. Regions dependent on coal, oil, or gas may need extra time to develop other sources of employment.' where slug='fossil-fuel-deadline' and id='d23fa8b1-ed81-5529-bb85-60c357669dc7';
update dk_safety.points set counterpoint='Plan for affected workers. Communities that rely on fossil fuel jobs would have a target date for training and new investment.' where slug='fossil-fuel-deadline' and id='5986d995-b270-5b21-85a8-4da28bac45d5';
update dk_safety.points set counterpoint='Match promises to funding. Countries could set dates around financing they can actually secure for the transition.' where slug='fossil-fuel-deadline' and id='397f018a-e5e2-5ad0-ad8c-97d510493f72';
update dk_safety.points set counterpoint='Finance has a schedule. A deadline can anchor talks about when countries need funding for power grids and cleaner energy.' where slug='fossil-fuel-deadline' and id='6d5612f4-b8d8-5a69-a9da-b983ae26e68b';
update dk_safety.points set counterpoint='A backup can fail too. A second tool can share the same sign-in provider, carrier, or network dependencies as the first.' where slug='cloud-outage-backup' and id='e2fa3332-85dc-54ef-b9ff-9a288b7c97a0';
update dk_safety.points set counterpoint='Reach staff during outages. A channel that uses a different provider or sign-in system can still work when the main apps are unavailable.' where slug='cloud-outage-backup' and id='ab86449b-d95a-5072-9d6f-026663558108';
update dk_safety.points set counterpoint='Avoid recurring fees. A subscription may be hard to justify for a small workplace that rarely needs simultaneous alerts.' where slug='cloud-outage-backup' and id='11007ba9-932c-5310-bccc-055f95897e7e';
update dk_safety.points set counterpoint='Fast notices reduce downtime. Employees can move to offline work or reschedule customer appointments while the main tools recover.' where slug='cloud-outage-backup' and id='3477c7ef-0a3e-5c34-b865-70ea18766f70';
update dk_safety.points set counterpoint='Collect less personal data. Using existing emergency contacts can avoid giving another vendor employee phone numbers.' where slug='cloud-outage-backup' and id='35716c23-76c9-57f5-a594-b615d5edafeb';
update dk_safety.points set counterpoint='Manage access to numbers. A properly configured alert system can limit who has access to employees’ personal contact details.' where slug='cloud-outage-backup' and id='faf54f22-2f4c-5fe2-bda8-6e4ce909fb79';
